$ErrorActionPreference='Stop';$repo=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$latestFile=Join-Path $repo 'artifacts\runs\yolomg_h264_repair_latest.json'
if(-not(Test-Path $latestFile)){throw "No repair pointer: $latestFile"};$latest=Get-Content $latestFile -Raw|ConvertFrom-Json;$processId=[int]$latest.coordinator_pid;$proc=Get-CimInstance Win32_Process -Filter "ProcessId = $processId" -ErrorAction SilentlyContinue
Write-Output "Repair coordinator: $(if($proc){'RUNNING'}else{'NOT RUNNING'})";Write-Output "PID: $processId";Write-Output "Start: $($latest.started_at)";if($proc){Write-Output "Command: $($proc.CommandLine)"}
if(Test-Path $latest.status_json){$s=Get-Content $latest.status_json -Raw|ConvertFrom-Json;Write-Output "Repair: status=$($s.status) done=$($s.done)/$($s.total) running=$($s.running) pending=$($s.pending) failed=$($s.failed) updated=$($s.updated_at)";foreach($i in $s.items){if($i.state -in @('running','failed')){Write-Output ("{0:D3} state={1} time={2:N1}/{3:N1}s PID={4}" -f [int]$i.sequence,$i.state,[double]$i.out_time_seconds,[double]$i.duration,$i.pid)}}}
Write-Output "Logs: $($latest.stdout_log) ; $($latest.stderr_log)";Write-Output "Results: $($latest.result_dir)";Write-Output "Backups: $($latest.backup_dir)";if(Test-Path $latest.stdout_log){Get-Content $latest.stdout_log -Tail 10};if(Test-Path $latest.stderr_log){$e=Get-Content $latest.stderr_log -Tail 10;if($e){Write-Output '--- stderr ---';$e}}
